test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 21 }],
  };
  const original = JSON.parse(JSON.stringify(invoice));
  invoiceTotals(invoice);
  assert.deepEqual(invoice, original);
});

test('invoiceTotals: no bulk discount for qty < 10', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 9000, no bulk discount, VAT: 1890, Total: 10890
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 10890);
});

test('invoiceTotals: applies bulk discount for qty = 10', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10000, bulk discount: 2.5% of 10000 = 250
  // After discount: 9750, VAT: 2047.5 → 2048, Total: 11798
  assert.equal(totals.discount, 250);
});

test('invoiceTotals: bulk discount is 2.5% of amount after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Line discount: 10% of 100000 = 10000
  // After line discount: 90000
  // Bulk discount: 2.5% of 90000 = 2250
  // Total discount: 10000 + 2250 = 12250
  assert.equal(totals.discount, 12250);
});

test('invoiceTotals: VAT applied after both discounts', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // After line discount: 90000
  // After bulk discount: 90000 - 2250 = 87750
  // VAT: 21% of 87750 = 18427.5 → 18428
  assert.equal(totals.vat, 18428);
});

test('invoiceTotals: bulk discount for high qty', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000, bulk discount: 2.5% of 100000 = 2500
  // After discount: 97500, VAT: 20475, Total: 117975
  assert.equal(totals.discount, 2500);
  assert.equal(totals.vat, 20475);
});

test('invoiceTotals: multiple lines with different quantities', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, vatRate: 21 },  // No bulk discount
      { qty: 10, unitPrice: 1000, vatRate: 21 }, // Has bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 5000, no bulk discount
  // Line 2: 10000, bulk discount: 250
  // Total discount: 250
  // Line 1 after discount: 5000, VAT: 1050
  // Line 2 after discount: 9750, VAT: 2048
  // Total VAT: 3098, Total: 15098
  assert.equal(totals.discount, 250);
  assert.equal(totals.subtotal, 15000);
});

test('invoiceTotals: bulk discount does not apply to qty = 9', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 0 },
      { qty: 10, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: no bulk discount
  // Line 2: bulk discount = 250
  // Total discount: 250
  assert.equal(totals.discount, 250);
});

test('invoiceTotals: bulk discount with existing line discount', () => {
  const invoice = {
    lines: [{ qty: 20, unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 20000
  // Line discount: 5% of 20000 = 1000
  // After line discount: 19000
  // Bulk discount: 2.5% of 19000 = 475
  // Total discount: 1000 + 475 = 1475
  // After both discounts: 18525
  // VAT: 21% of 18525 = 3890.25 → 3890
  // Total: 20000 - 1475 + 3890 = 22415
  assert.equal(totals.discount, 1475);
});

test('invoiceTotals: bulk discount with zero line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Line discount: 0
  // After line discount: 10000
  // Bulk discount: 2.5% of 10000 = 250
  // Total discount: 250
  assert.equal(totals.discount, 250);
});

test('invoiceTotals: bulk discount with 100% line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Line discount: 100% of 10000 = 10000 (clamped)
  // After line discount: 0 (clamped)
  // Bulk discount: 2.5% of 0 = 0
  // Total discount: 10000
  assert.equal(totals.discount, 10000);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: bulk discount with many lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, vatRate: 0 },
      { qty: 10, unitPrice: 1000, vatRate: 0 },
      { qty: 15, unitPrice: 1000, vatRate: 0 },
      { qty: 3, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 5000, no bulk discount
  // Line 2: 10000, bulk discount: 250
  // Line 3: 15000, bulk discount: 375
  // Line 4: 3000, no bulk discount
  // Total discount: 250 + 375 = 625
  // Subtotal: 33000
  // Total: 33000 - 625 = 32375
  assert.equal(totals.discount, 625);
  assert.equal(totals.total, 32375);
});

test('invoiceTotals: bulk discount with tier discount', () => {
  // Note: tier discount is applied at line creation, stored as discountPercent
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Line discount (tier): 5% of 100000 = 5000
  // After line discount: 95000
  // Bulk discount: 2.5% of 95000 = 2375
  // Total discount: 5000 + 2375 = 7375
  assert.equal(totals.discount, 7375);
});

test('invoiceTotals: bulk discount with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Bulk discount: 2.5% of 100000 = 2500
  // After discount: 97500
  // VAT: 21% of 97500 = 20475
  // Before voucher: 117975
  // After voucher: 112975
  assert.equal(totals.discount, 2500);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 112975);
});

test('invoiceTotals: bulk discount with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21 },
      { qty: 10, unitPrice: 10000, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 100000, bulk discount: 2500, after: 97500, VAT: 20475
  // Line 2: 100000, bulk discount: 2500, after: 97500, VAT: 8775
  // Total discount: 5000
  // Total VAT: 29250
  // Total: 200000 - 5000 + 29250 = 224250
  assert.equal(totals.discount, 5000);
  assert.equal(totals.vat, 29250);
});

test('invoiceTotals: bulk discount edge case qty = 9.5 (treated as 9)', () => {
  // qty should always be an integer, but test safety
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // No bulk discount for qty < 10
  assert.equal(totals.discount, 0);
});

test('invoiceTotals: bulk discount calculation with rounding', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9999, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 99990
  // Bulk discount: 2.5% of 99990 = 2499.75 → 2500 (banker's rounding)
  // After discount: 97490
  // VAT: 21% of 97490 = 20472.9 → 20473
  // Total: 99990 - 2500 + 20473 = 117963
  assert.equal(totals.discount, 2500);
});

