test('invoiceTotals: total clamped at 0 even with VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 200, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Line total: 100 cents
  // Discount: 200% of 100 = 200 cents (clamped)
