  assert.equal(totals.subtotal, 500 + 1000); // 1500
  // Line 1: 20% of 500 = 100, no bulk discount (qty < 10)
  // Line 2: 10% of 1000 = 100, bulk discount: 2.5% of 900 = 22.5 → 23 (banker's rounding)
  assert.equal(totals.discount, 100 + 100 + 23); // 223
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 1277);
});

