test('createInvoice: tier discount is included in totals', () => {
  const result = createInvoice({
    customerId: 'C-001', // Northwind Studio, tier: gold (5%)
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000 cents
  // Line discount: 5% of 95000 = 4750 cents
  // After line discount: 95000 - 4750 = 90250 cents
  // Bulk discount: 2.5% of 90250 = 2256.25 → 2256 cents (banker's rounding)
  // Total discount: 4750 + 2256 = 7006 cents
  // After discounts: 95000 - 7006 = 87994 cents
  // VAT: 21% of 87994 = 18478.74 → 18479 cents (banker's rounding)
  // Total: 87994 + 18479 = 106473 cents
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18479);
  assert.equal(totals.total, 106473);
});

