      { qty: 5, unitPrice: 1000, vatRate: 0 },
      { qty: 10, unitPrice: 1000, vatRate: 0 },
      { qty: 15, unitPrice: 1000, vatRate: 0 },
      { qty: 3, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 5000, no bulk discount
  // Line 2: 10000, bulk discount: 250
  // Line 3: 15000, bulk discount: 375
  // Line 4: 3000, no bulk discount
  // Total discount: 250 + 375 = 625
  // Subtotal: 33000
  // Total: 33000 - 625 = 32375
  assert.equal(totals.discount, 625);
  assert.equal(totals.total, 32375);
});

test('invoiceTotals: bulk discount with tier discount', () => {
  // Note: tier discount is applied at line creation, stored as discountPercent
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Line discount (tier): 5% of 100000 = 5000
  // After line discount: 95000
  // Bulk discount: 2.5% of 95000 = 2375
  // Total discount: 5000 + 2375 = 7375
  assert.equal(totals.discount, 7375);
});

test('invoiceTotals: bulk discount with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Bulk discount: 2.5% of 100000 = 2500
  // After discount: 97500
  // VAT: 21% of 97500 = 20475
  // Before voucher: 117975
  // After voucher: 112975
  assert.equal(totals.discount, 2500);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 112975);
});

test('invoiceTotals: bulk discount with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21 },
      { qty: 10, unitPrice: 10000, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 100000, bulk discount: 2500, after: 97500, VAT: 20475
  // Line 2: 100000, bulk discount: 2500, after: 97500, VAT: 8775
  // Total discount: 5000
  // Total VAT: 29250
  // Total: 200000 - 5000 + 29250 = 224250
  assert.equal(totals.discount, 5000);
  assert.equal(totals.vat, 29250);
});

test('invoiceTotals: bulk discount edge case qty = 9.5 (treated as 9)', () => {
  // qty should always be an integer, but test safety
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // No bulk discount for qty < 10
  assert.equal(totals.discount, 0);
});

test('invoiceTotals: bulk discount calculation with rounding', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 9999, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 99990
  // Bulk discount: 2.5% of 99990 = 2499.75 → 2500 (banker's rounding)
  // After discount: 97490
  // VAT: 21% of 97490 = 20472.9 → 20473
  // Total: 99990 - 2500 + 20473 = 117963
  assert.equal(totals.discount, 2500);
});

